}

async dispose(): Promise<void> {
  if (this.cleanupFinished) return;
  if (this.disposal !== undefined) return this.disposal;
  this.disposal = this.performDispose();
  try {
    await this.disposal;
  } finally {
    this.disposal = undefined;
  }
}

